"""Original six-sided pencil shaft with real recessed angular eyes, Blender 4.3."""
import bpy,json,math,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[2];out=root/'.art/school-pencil-sculpt';out.mkdir(parents=True,exist_ok=True)
bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False)
verts=[(.12*math.sin(i*math.tau/6),y,.12*math.cos(i*math.tau/6)) for y in [-.325,.385] for i in range(6)]
faces=[tuple(range(5,-1,-1)),tuple(range(6,12))]+[(i,(i+1)%6,(i+1)%6+6,i+6) for i in range(6)]
m=bpy.data.meshes.new('hexagonal-shaft');m.from_pydata(verts,[],faces);m.update();o=bpy.data.objects.new('carved-lacquered-shaft',m);bpy.context.collection.objects.link(o)
bpy.context.view_layer.objects.active=o;o.select_set(True)
# Recalculate normals independently of hand-authored winding.
bpy.ops.object.mode_set(mode='EDIT');bpy.ops.mesh.select_all(action='SELECT');bpy.ops.mesh.normals_make_consistent(inside=False);bpy.ops.mesh.quads_convert_to_tris(quad_method='BEAUTY',ngon_method='BEAUTY');bpy.ops.object.mode_set(mode='OBJECT')
for s in [-1,1]:
 xy=[(s*x,y) for x,y in [(.012,-.062),(.103,-.025),(.086,-.093),(.031,-.112)]]
 vs=[(x,y,z) for z in [-.17,-.055] for x,y in xy];fs=[(3,2,1,0),(4,5,6,7)]+[(i,(i+1)%4,(i+1)%4+4,i+4) for i in range(4)]
 cm=bpy.data.meshes.new('eye-cut');cm.from_pydata(vs,[],fs);cm.update();c=bpy.data.objects.new('eye-cut',cm);bpy.context.collection.objects.link(c)
 bpy.ops.object.select_all(action='DESELECT');c.select_set(True);bpy.context.view_layer.objects.active=c;bpy.ops.object.mode_set(mode='EDIT');bpy.ops.mesh.select_all(action='SELECT');bpy.ops.mesh.normals_make_consistent(inside=False);bpy.ops.object.mode_set(mode='OBJECT')
 bpy.context.view_layer.objects.active=o;mod=o.modifiers.new('actual socket depression','BOOLEAN');mod.operation='DIFFERENCE';mod.solver='EXACT';mod.object=c;bpy.ops.object.modifier_apply(modifier=mod.name);bpy.data.objects.remove(c,do_unlink=True)
bpy.context.view_layer.objects.active=o
bevel=o.modifiers.new('worn lacquer cut edges','BEVEL');bevel.width=.0018;bevel.segments=2;bpy.ops.object.modifier_apply(modifier=bevel.name)
# Boolean ngons can retain inconsistent winding after bevel; repair the actual mesh topology,
# then triangulate before serializing (not merely flipping exported normals).
bpy.ops.object.select_all(action='DESELECT');o.select_set(True);bpy.context.view_layer.objects.active=o
bpy.ops.object.mode_set(mode='EDIT');bpy.ops.mesh.select_all(action='SELECT');bpy.ops.mesh.normals_make_consistent(inside=False);bpy.ops.mesh.quads_convert_to_tris(quad_method='BEAUTY',ngon_method='BEAUTY');bpy.ops.mesh.normals_make_consistent(inside=False);bpy.ops.object.mode_set(mode='OBJECT')
m=o.data;m.calc_loop_triangles();p=[];n=[];uv=[]
for tri in m.loop_triangles:
 for i in tri.vertices:
  v=m.vertices[i].co;p.extend(round(x,7) for x in v);n.extend(round(x,7) for x in tri.normal);uv.extend([(math.atan2(v.x,v.z)/math.tau)%1,(v.y+.325)/.71])
data={'position':p,'normal':n,'uv':uv};encoded=json.dumps(data,separators=(',',':'))
(root/'src/visual/creatures/v2/schoolPencilGeometry.ts').write_text('// Generated by scripts/art/sculpt-school-pencil.py\nexport const schoolPencilShaftData = '+encoded+';\n')
bpy.ops.wm.save_as_mainfile(filepath=str(out/'pencil-shaft-authoring.blend'),compress=True)
(out/'manifest.json').write_text(json.dumps({'triangles':len(p)//9,'geometrySha256':hashlib.sha256(encoded.encode()).hexdigest()},indent=2));print('CARVED_PENCIL',len(p)//9)
